const products=[
{id:'shampoo',name:'Everyday care shampoo',category:'Haircare',price:1800,form:'bottle',tone:'sage',size:'250 ml · example',description:'A place for Pippin’s chosen everyday shampoo. The brand, ingredients and suitability information will be added with the confirmed product range.'},
{id:'conditioner',name:'Soft finish conditioner',category:'Haircare',price:2000,form:'bottle',tone:'cream',size:'250 ml · example',description:'An example conditioner listing. This product page will hold the actual description, directions and ingredients before sales open.'},
{id:'spray',name:'Styling preparation spray',category:'Styling',price:1600,form:'spray',tone:'pink',size:'150 ml · example',description:'An example styling product. Pippin’s chosen brand and approved product guidance will appear here.'},
{id:'brush',name:'Blow-dry brush',category:'Accessories',price:1400,form:'brush',tone:'sand',size:'Medium · example',description:'An example accessory listing. Size, materials and care instructions will be confirmed for the real product.'}
];
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n/100);let cart={};try{const data=JSON.parse(localStorage.getItem('pip-shop-demo')||'{}');for(const p of products)if(Number.isInteger(data[p.id])&&data[p.id]>0)cart[p.id]=Math.min(10,data[p.id]);}catch{}
const art=p=>`<div class="product-art ${p.tone}"><span class="product-object ${p.form}"><small>THE<br>SNIPPITYPIP</small><b>${p.category==='Accessories'?'STYLE':'CARE'}</b></span><span class="art-caption">Illustrative packaging</span></div>`;
function save(){try{localStorage.setItem('pip-shop-demo',JSON.stringify(cart));}catch{}document.querySelector('#basket-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);}
function add(id){cart[id]=Math.min(10,(cart[id]||0)+1);save();document.querySelector('#shop-status').textContent=products.find(p=>p.id===id).name+' added to your preview basket.';}
function list(category='All'){document.querySelector('#products').innerHTML=products.filter(p=>category==='All'||p.category===category).map(p=>`<article class="product-card"><a href="#product/${p.id}" aria-label="View ${p.name}">${art(p)}</a><div class="product-meta"><span class="eyebrow">${p.category} · Example</span><h2><a href="#product/${p.id}">${p.name}</a></h2><p>${p.size}</p><div class="product-bottom"><strong>${money(p.price)}</strong><button class="portal-quiet" data-add="${p.id}">Add to basket +</button></div></div></article>`).join('');document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(b.dataset.add));}
function basket(){const selected=products.filter(p=>cart[p.id]);document.querySelector('#basket-items').innerHTML=selected.length?selected.map(p=>`<div class="basket-row"><div><h3>${p.name}</h3><p>${money(p.price)} each · example price</p><button class="text-link" data-remove="${p.id}">Remove</button></div><div><label for="qty-${p.id}">Quantity</label><input id="qty-${p.id}" data-qty="${p.id}" type="number" min="1" max="10" value="${cart[p.id]}"><strong>${money(p.price*cart[p.id])}</strong></div></div>`).join(''):'<p>Your basket is waiting for a little inspiration.</p>';const total=selected.reduce((sum,p)=>sum+p.price*cart[p.id],0);document.querySelector('#basket-summary').innerHTML=selected.length?`<div class="basket-total"><span>Example subtotal</span><strong>${money(total)}</strong></div><p class="small muted">Delivery and collection options are not yet configured.</p><button class="btn" disabled style="width:100%">Checkout opening soon</button><p class="shop-notice">Stripe payments are not connected in this preview. No order will be placed and no payment details are collected.</p>`:'<button class="btn" data-continue>Explore the collection</button>';document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{delete cart[b.dataset.remove];save();basket();});document.querySelectorAll('[data-qty]').forEach(b=>b.oninput=()=>{cart[b.dataset.qty]=Math.max(1,Math.min(10,Math.floor(Number(b.value)||1)));save();b.parentElement.querySelector('strong').textContent=money(products.find(p=>p.id===b.dataset.qty).price*cart[b.dataset.qty]);document.querySelector('.basket-total strong').textContent=money(products.reduce((n,p)=>n+p.price*(cart[p.id]||0),0));});document.querySelector('[data-continue]')?.addEventListener('click',()=>document.querySelector('#basket-dialog').close());}
function detail(){const p=products.find(p=>'#product/'+p.id===location.hash);if(!p)return;document.querySelector('#product-detail').innerHTML=`${art(p)}<span class="eyebrow">${p.category} · Preview product</span><h2 id="product-title">${p.name}</h2><p>${p.size}</p><h3>${money(p.price)} <small>example price</small></h3><p>${p.description}</p><button class="btn" id="detail-add">Add to preview basket +</button><p class="small muted">Demonstration only. This is not a confirmed item for sale.</p>`;const dialog=document.querySelector('#product-dialog');if(!dialog.open)dialog.showModal();document.querySelector('#detail-add').onclick=()=>{add(p.id);dialog.close();basket();document.querySelector('#basket-dialog').showModal();};}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',x===b));list(b.dataset.category);});document.querySelector('#open-basket').onclick=()=>{basket();document.querySelector('#basket-dialog').showModal();};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelector('#product-dialog').addEventListener('close',()=>{if(location.hash.startsWith('#product/'))history.replaceState(null,'',location.pathname+'#collection');});window.addEventListener('hashchange',detail);save();list();detail();
